.control
* 1. DC Operating Point and Power Dissipation
op
let pwr = -i(VDD) * 1.8
print pwr

* 2. Open-Loop AC Analysis (Frequency Response, Gain, PM, GM, fun)
ac dec 100 1 1G
let aol_db = vdb(vout)
let aol_ph = 180 / PI * cph(v(vout))

meas ac open_loop_dc_gain find aol_db at=10
meas ac aol_3db_val eval open_loop_dc_gain-3
meas ac dominant_pole_frequency when aol_db=aol_3db_val fall=1
meas ac unity_gain_frequency when aol_db=0 fall=1
meas ac phase_at_unity find aol_ph when aol_db=0 fall=1
let pm = 180 + phase_at_unity
print pm

meas ac f_180 when aol_ph=-180 fall=1
meas ac gain_at_180 find aol_db when aol_ph=-180 fall=1
let gm = -gain_at_180
print gm

* 3. DC Sweep for Output Voltage Swing and Systematic Offset
dc Vp 0.88 0.92 0.1m
meas dc systematic_offset_voltage when v(vout)=0.9 cross=1
meas dc output_voltage_swing_max max v(vout)
meas dc output_voltage_swing_min min v(vout)

print open_loop_dc_gain unity_gain_frequency dominant_pole_frequency systematic_offset_voltage
quit
.endc
.end

